(()=>{console.log("[Flow Content Script] Active on:",window.location.href);const o=new URLSearchParams(window.location.search).get("flow_grant");o&&(console.log("[Flow Content Script] Detected flow_grant in URL. Registering delegated session."),sessionStorage.setItem("flow_delegated_session",o),window.postMessage({source:"flow_session_share",type:"FLOW_SESSION_DELEGATED",token:o},"*")),chrome.runtime.sendMessage({type:"GET_ACTIVE_DELEGATED_SESSION",domain:window.location.origin},e=>{e!=null&&e.session&&console.log("[Flow Content Script] Verified active delegated session for domain:",window.location.origin)})})();
